-- END CANONICAL TECHNICAL EXPECTATION PROJECTION

-- Change only the exact reviewed prospective predicates. Preserve OIDs, ACLs,
-- ownership, SECURITY DEFINER, search_path, names and all other pg_proc fields.
DO $prospective_selection$
DECLARE f record;needle text;replacement text;body text;
BEGIN
 SELECT p.oid,to_jsonb(p)-'prosrc' metadata,p.prosrc,pg_get_functiondef(p.oid) definition INTO STRICT f FROM pg_proc p WHERE p.oid='public.resolve_canonical_ediel_rule_pack(text,text,text,text,text,date)'::regprocedure;
 IF encode(sha256(convert_to(f.prosrc,'UTF8')),'hex')<>'6c0d7896f26176338f70e918676a4368e0c3040a1e5ed6e6a5da83553f2b26a4' THEN RAISE EXCEPTION 'ediel_u5_selector_predecessor_required';END IF;
 needle:='and rp.status in (''active'',''transition'',''future'')';
 IF (length(f.prosrc)-length(replace(f.prosrc,needle,'')))/length(needle)<>2 THEN RAISE EXCEPTION 'ediel_u5_selector_predicates_required';END IF;
 replacement:=needle||E'\n    and NOT gridex_ediel_source_rules.pack_superseded_by_swedish_utilts25a5_v1(rp.market,rp.family,rp.guide_version,rp.guide_revision,p_business_date)';
 body:=replace(f.prosrc,needle,replacement);EXECUTE replace(f.definition,f.prosrc,body);
 IF (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE p.oid=f.oid) IS DISTINCT FROM f.metadata THEN RAISE EXCEPTION 'ediel_u5_selector_metadata_changed';END IF;
 SELECT p.oid,to_jsonb(p)-'prosrc' metadata,p.prosrc,pg_get_functiondef(p.oid) definition INTO STRICT f FROM pg_proc p WHERE p.oid='gridex_ediel_source_rules.pack_effective_v1(uuid,text,date)'::regprocedure;
 IF encode(sha256(convert_to(f.prosrc,'UTF8')),'hex')<>'bdf66d7fbda88628459f0ea0606d51748fe675cfee34cafa90374de2c69b7d37' THEN RAISE EXCEPTION 'ediel_u5_effective_predecessor_required';END IF;
 needle:='WHERE r.id=p_pack_id AND r.status';replacement:='WHERE r.id=p_pack_id AND NOT gridex_ediel_source_rules.pack_superseded_by_swedish_utilts25a5_v1(r.market,r.family,r.guide_version,r.guide_revision,p_date) AND r.status';
 IF (length(f.prosrc)-length(replace(f.prosrc,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION 'ediel_u5_effective_predicate_required';END IF;
 EXECUTE replace(f.definition,f.prosrc,replace(f.prosrc,needle,replacement));
 IF (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE p.oid=f.oid) IS DISTINCT FROM f.metadata THEN RAISE EXCEPTION 'ediel_u5_effective_metadata_changed';END IF;
END $prospective_selection$;

-- The logical mapping has no guide choice; keep its existing body byteexact.
-- National technical policy selects a fixed edition by protected original,
-- never by today, caller policy or latest installation. Preserve old validator.
DO $protected_technical_routing$
DECLARE f record;definition text;body text;old_projection jsonb;new_projection jsonb;
BEGIN
 SELECT projection INTO STRICT old_projection FROM gridex_ediel_transport.technical_expectation_editions WHERE source_version='05abbd87fb53e2a4e5e0583741e4dad6fed9f525010420e93c12e9b5c3dfda98';
 SELECT projection INTO STRICT new_projection FROM gridex_ediel_transport.technical_expectation_editions WHERE source_version='215af3f4794d17c84711e91071e48f713a1165741d2697c89bbed267571d8466';
 IF old_projection->'logicalCodes' IS DISTINCT FROM new_projection->'logicalCodes' OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='gridex_ediel_transport.canonical_message_code_v1(text,text)'::regprocedure)<>'ec61c020ee436da9fff5144e7b1323a54c6282573c5c8e5c51d43cc51e5f1ae1' THEN RAISE EXCEPTION 'ediel_u5_logical_identity_changed';END IF;
 SELECT p.oid,to_jsonb(p)-'prosrc' metadata,p.prosrc,pg_get_functiondef(p.oid) definition INTO STRICT f FROM pg_proc p WHERE p.oid='gridex_ediel_transport.require_technical_expectation_plan_v1(public.ediel_messages,jsonb)'::regprocedure;
 IF encode(sha256(convert_to(f.prosrc,'UTF8')),'hex')<>'dc61697f0478860023f76c3dd8e339d6186edb2d057a108f0ff1d98d308ba8be' THEN RAISE EXCEPTION 'ediel_u5_technical_predecessor_required';END IF;
 definition:=replace(f.definition,'FUNCTION gridex_ediel_transport.require_technical_expectation_plan_v1(','FUNCTION gridex_ediel_transport.require_technical_expectation_plan_before_swedish_utilts25a5_v1(');EXECUTE definition;
 body:=replace(f.prosrc,'05abbd87fb53e2a4e5e0583741e4dad6fed9f525010420e93c12e9b5c3dfda98','215af3f4794d17c84711e91071e48f713a1165741d2697c89bbed267571d8466');
 definition:=replace(replace(f.definition,f.prosrc,body),'FUNCTION gridex_ediel_transport.require_technical_expectation_plan_v1(','FUNCTION gridex_ediel_transport.require_technical_expectation_plan_swedish_utilts25a5_v1(');EXECUTE definition;
 body:=$route$
DECLARE basis jsonb;r jsonb;
BEGIN
 -- Preserve non-applicable/unknown/invalid-scope and common-header old lanes
 -- before any additional protected national-basis read.
 IF m.direction IS DISTINCT FROM 'outbound' OR m.company_id IS NULL OR m.environment IS NULL OR m.environment NOT IN('test','production') OR m.message_family IS NULL OR m.message_family NOT IN('UTILTS','UTILTS_ERR','APERAK') OR m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL THEN
  RETURN gridex_ediel_transport.require_technical_expectation_plan_before_swedish_utilts25a5_v1(m,p_plan);
 END IF;
 basis:=gridex_ediel_source_rules.require_v1(m.company_id,m.id);r:=basis#>'{snapshot,rulePack}';
 IF r->>'family'='UTILTS' AND r->>'guide_version'='25-A-5' AND r->>'guide_revision'='5' THEN
  IF basis->>'version' IS DISTINCT FROM '25-A-5:r5' OR basis#>>'{snapshot,version}' IS DISTINCT FROM basis->>'version'
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(basis#>'{snapshot,guideSources}')s WHERE s->>'source_type'='technical_guide' AND s->>'revision'='25-A-5' AND s->>'source_hash'='b76a61b9aa6f136771e5db4948296d1b632b8d775314eb6c93783595ae419db2' AND nullif(btrim(s->>'source_locator'),'') IS NOT NULL) THEN RAISE EXCEPTION 'ediel_technical_expectation_u5_original_primary_required';END IF;
  RETURN gridex_ediel_transport.require_technical_expectation_plan_swedish_utilts25a5_v1(m,p_plan);
 END IF;
 RETURN gridex_ediel_transport.require_technical_expectation_plan_before_swedish_utilts25a5_v1(m,p_plan);
END
$route$;
 EXECUTE replace(f.definition,f.prosrc,body);
 IF (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE p.oid=f.oid) IS DISTINCT FROM f.metadata THEN RAISE EXCEPTION 'ediel_u5_technical_metadata_changed';END IF;
END $protected_technical_routing$;
REVOKE ALL ON FUNCTION gridex_ediel_transport.require_technical_expectation_plan_before_swedish_utilts25a5_v1(public.ediel_messages,jsonb),gridex_ediel_transport.require_technical_expectation_plan_swedish_utilts25a5_v1(public.ediel_messages,jsonb) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
